<?= $this->extend('layout') ?><?= $this->section('content') ?><?php $med=$charts['medications'];$clients=$charts['clients'];$months=$charts['months'];$ages=$charts['ages'];$monthLabels=array_values(array_unique(array_column($months,'month')));$types=array_values(array_unique(array_column($months,'Type')));$gender=array_values(array_unique(array_column($ages,'Genre')));$ageLabels=array_values(array_unique(array_column($ages,'Age')));$palette=['rgba(10,108,188,.6)','rgba(0,184,148,.6)','rgba(99,102,241,.6)','rgba(245,158,11,.6)','rgba(229,83,83,.6)']; ?><div class="dv-page-header"><h1><i class="bi bi-bar-chart-line" style="color:var(--accent);margin-right:8px"></i>Représentation graphique</h1></div><div class="dv-stats-grid"><div class="dv-stat primary"><div class="dv-stat-label">Médicaments</div><div class="dv-stat-value"><?= number_format(array_sum(array_column($med,'value'))) ?></div></div><div class="dv-stat success"><div class="dv-stat-label">Clients</div><div class="dv-stat-value"><?= number_format(array_sum(array_column($clients,'value'))) ?></div></div><div class="dv-stat info"><div class="dv-stat-label">Types</div><div class="dv-stat-value"><?= count($med) ?></div></div><div class="dv-stat warning"><div class="dv-stat-label">Tranches d'âge</div><div class="dv-stat-value"><?= count($ageLabels) ?></div></div></div><div class="dv-card"><div class="dv-card-header"><i class="bi bi-bar-chart"></i>Médicaments par type</div><canvas id="byType" height="80"></canvas></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:20px"><div class="dv-card"><div class="dv-card-header"><i class="bi bi-bar-chart-steps"></i>Médicaments par mois</div><canvas id="byMonth"></canvas></div><div class="dv-card"><div class="dv-card-header"><i class="bi bi-pie-chart"></i>Type de clients</div><canvas id="byClient"></canvas></div></div><div class="dv-card"><div class="dv-card-header"><i class="bi bi-people"></i>Clients par âge et genre</div><canvas id="byAge" height="80"></canvas></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const med=<?= json_encode($med,JSON_UNESCAPED_UNICODE) ?>,clients=<?= json_encode($clients,JSON_UNESCAPED_UNICODE) ?>,monthLabels=<?= json_encode($monthLabels) ?>,types=<?= json_encode($types,JSON_UNESCAPED_UNICODE) ?>,months=<?= json_encode($months,JSON_UNESCAPED_UNICODE) ?>,ageLabels=<?= json_encode($ageLabels) ?>,gender=<?= json_encode($gender,JSON_UNESCAPED_UNICODE) ?>,ages=<?= json_encode($ages,JSON_UNESCAPED_UNICODE) ?>,colors=<?= json_encode($palette) ?>;const option={responsive:true,scales:{y:{beginAtZero:true}}};new Chart(byType,{type:'bar',data:{labels:med.map(x=>x.label),datasets:[{label:'Nombre de médicaments',data:med.map(x=>x.value),backgroundColor:colors[0]}]},options:option});new Chart(byClient,{type:'pie',data:{labels:clients.map(x=>x.label),datasets:[{data:clients.map(x=>x.value),backgroundColor:colors}]}});new Chart(byMonth,{type:'bar',data:{labels:monthLabels,datasets:types.map((t,i)=>({label:t,backgroundColor:colors[i%colors.length],data:monthLabels.map(m=>(months.find(x=>x.month===m&&x.Type===t)||{value:0}).value)}))},options:option});new Chart(byAge,{type:'bar',data:{labels:ageLabels,datasets:gender.map((g,i)=>({label:g,backgroundColor:colors[i],data:ageLabels.map(a=>(ages.find(x=>x.Age==a&&x.Genre===g)||{value:0}).value)}))},options:option});</script><?= $this->endSection() ?>
